"""Get all keys of nested dict

    Parameters
    ----------
    nested_dict : dict
        Nested dictionary

    Return
    ------
    all_nested_keys : list
        Key of nested dict
    """
def get_nested_dict_key(nested_dict: Any) -> object {
    all_nested_keys = [];
    for `entry in nested_dict {
        for value in nested_dict[`entry].keys() {
            all_nested_keys.append(value);
        }
    }
    return all_nested_keys;
}

test_blocks:
test "t0" {
    assert (
        get_nested_dict_key({"a": {"b": 2, "c": 3}, "d": {"e": 4, "f": 5}})
        == ["b", "c", "e", "f"]
    );;
}

test "t1" {
    assert (get_nested_dict_key({"1": {"a": 1, "b": 2}}) == ["a", "b"]);;
}

test "t2" {
    assert (
        get_nested_dict_key({1: {"a": 0, "b": 1}, 2: {"c": 3, "d": 4}})
        == ["a", "b", "c", "d"]
    );;
}

test "t3" {
    assert (get_nested_dict_key({}) == []);;
}
